export type ParsedRecordCollectionInstruction<
  TProgram extends string = typeof PICKPAY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    hub: TAccountMetas[1];
    collection: TAccountMetas[2];
    /** Fails with "already in use" if this exact photo was recorded before. */
    photoSeal: TAccountMetas[3];
    picker: TAccountMetas[4];
    mint: TAccountMetas[5];
    escrow: TAccountMetas[6];
    /** The picker's wallet token account. Omit it to accrue the payout to the picker's claim balance. */
    pickerToken?: TAccountMetas[7] | undefined;
    tokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: RecordCollectionInstructionData;
};

export function parseRecordCollectionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRecordCollectionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === PICKPAY_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      hub: getNextAccount(),
      collection: getNextAccount(),
      photoSeal: getNextAccount(),
      picker: getNextAccount(),
      mint: getNextAccount(),
      escrow: getNextAccount(),
      pickerToken: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRecordCollectionInstructionDataDecoder().decode(instruction.data),
  };
}
